def longest(num):
    x = num & 0xFFFFFFFF
    best = cur = prev = 0
    for i in range(32):
        if x >> i & 1:
            cur += 1
        else:
            prev, cur = cur, 0
        best = max(best, prev + cur + 1)
    return min(best, 32)


