def magic(a, lo, hi):
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    v = a[mid]
    left = magic(a, lo, min(mid - 1, v))
    if left != -1:
        return left
    if v == mid:
        return mid
    return magic(a, max(mid + 1, v), hi)


