from bisect import bisect_left


def find_break(a):
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        elif a[mid] < a[hi]:
            hi = mid
        else:
            if a[hi - 1] > a[hi]:
                return hi
            hi -= 1
    return lo


