import sys


def find(words, target):
    lo, hi = 0, len(words) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if words[mid] == '#':
            left, right = mid - 1, mid + 1
            while True:
                if left < lo and right > hi:
                    return -1
                if right <= hi and words[right] != '#':
                    mid = right
                    break
                if left >= lo and words[left] != '#':
                    mid = left
                    break
                left -= 1
                right += 1
        if words[mid] == target:
            return mid
        if target < words[mid]:
            hi = mid - 1
        else:
            lo = mid + 1
    return -1


