import sys
from fractions import Fraction


def cross(ax, ay, bx, by):
    return ax * by - ay * bx


def on_segment(p, a, b):
    """p is known to be on line ab; check it lies within the bounding box."""
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])


def meet(p1, p2, p3, p4):
    rx, ry = p2[0] - p1[0], p2[1] - p1[1]
    sx, sy = p4[0] - p3[0], p4[1] - p3[1]
    qx, qy = p3[0] - p1[0], p3[1] - p1[1]
    d = cross(rx, ry, sx, sy)
    if d != 0:
        t = Fraction(cross(qx, qy, sx, sy), d)
        u = Fraction(cross(qx, qy, rx, ry), d)
        if 0 <= t <= 1 and 0 <= u <= 1:
            return (p1[0] + t * rx, p1[1] + t * ry)
        return None
    if cross(qx, qy, rx, ry) != 0:
        return None                      # parallel, different lines
    shared = [p for p in (p1, p2, p3, p4) if on_segment(p, p1, p2) and on_segment(p, p3, p4)]
    return min(shared) if shared else None


def main():
    a = list(map(int, sys.stdin.read().split()))
    p = meet((a[0], a[1]), (a[2], a[3]), (a[4], a[5]), (a[6], a[7]))
    if p is None:
        print(0)
    else:
        print('2 %.10f %.10f' % (float(p[0]), float(p[1])))


