import sys


def negate(x):
    return ~x + 1


def multiply(a, b):
    # 倍增：把 |b| 拆成 2 的幂，对应地累加 |a| 的倍数
    neg = (a < 0) != (b < 0)
    a, b = abs(a), abs(b)
    res = 0
    while b:
        if b & 1:
            res += a
        a += a
        b >>= 1
    return negate(res) if neg else res


def divide(a, b):
    # 从大到小尝试 |b|·2^k，能减就减；商的绝对值向零取整
    neg = (a < 0) != (b < 0)
    a, b = abs(a), abs(b)
    q = 0
    for k in range(31, -1, -1):
        if (b << k) <= a:
            a += negate(b << k)
            q += 1 << k
    return negate(q) if neg else q


def main():
    lines = sys.stdin.read().split('\n')
    t = int(lines[0])
    out = []
    for line in lines[1:t + 1]:
        x, op, y = line.split()
        a, b = int(x), int(y)
        if op == '-':
            out.append(a + negate(b))
        elif op == '*':
            out.append(multiply(a, b))
        else:
            out.append(divide(a, b))
    print('\n'.join(map(str, out)))


