def matches(pattern, value):
    ca, cb = pattern.count('a'), pattern.count('b')
    n = len(value)
    for la in range(n // ca + 1 if ca else 1):
        rest = n - ca * la
        if cb == 0:
            if rest != 0:
                continue
            lb = 0
        else:
            if rest % cb:
                continue
            lb = rest // cb
        piece = {'a': None, 'b': None}
        pos, ok = 0, True
        for c in pattern:
            length = la if c == 'a' else lb
            part = value[pos:pos + length]
            pos += length
            if piece[c] is None:
                piece[c] = part
            elif piece[c] != part:
                ok = False
                break
        # 两个字母都出现时，对应的串不能相同
        if ok and piece['a'] != piece['b']:
            return True
    return False


