def count_twos(n):
    total, base = 0, 1
    while base <= n:
        high, cur, low = n // (base * 10), n // base % 10, n % base
        if cur < 2:
            total += high * base
        elif cur == 2:
            total += high * base + low + 1
        else:
            total += (high + 1) * base
        base *= 10
    return total


