def can_fill(rows, prefixes, full, length, height):
    cols = [""] * length

    def go(depth):
        if depth == height:
            return all(c in full for c in cols)
        for w in rows:
            nxt = [cols[k] + w[k] for k in range(length)]
            if all(c in prefixes for c in nxt):
                saved = cols[:]
                cols[:] = nxt
                if go(depth + 1):
                    return True
                cols[:] = saved
        return False

    return go(0)


