import sys
from collections import deque


class Node:
    __slots__ = ('val', 'left', 'right')

    def __init__(self, val):
        self.val = val
        self.left = self.right = None


def build(line):
    tokens = line.split()
    if not tokens or tokens[0] == 'null':
        return None
    root = Node(int(tokens[0]))
    queue, i = deque([root]), 1
    while queue and i < len(tokens):
        node = queue.popleft()
        for side in ('left', 'right'):
            if i < len(tokens):
                if tokens[i] != 'null':
                    child = Node(int(tokens[i]))
                    setattr(node, side, child)
                    queue.append(child)
                i += 1
    return root


def covers(a, b):
    stack = [(a, b)]
    while stack:
        x, y = stack.pop()
        if y is None:
            continue
        if x is None or x.val != y.val:
            return False
        stack.append((x.left, y.left))
        stack.append((x.right, y.right))
    return True


def main():
    lines = sys.stdin.read().split('\n')
    a, b = build(lines[0]), build(lines[1])
    stack = [a]
    while stack:
        x = stack.pop()
        if x is None:
            continue
        if covers(x, b):
            print('true')
            return
        stack.append(x.left)
        stack.append(x.right)
    print('false')


